"""Canonical rows (Processing Design v0.1 §2–§4) and the checks every stage runs on them."""
from __future__ import annotations

import math
import re
from collections import Counter
from dataclasses import dataclass
from typing import Sequence

from .dictionary import Dictionary
from .values import parse_decimal

BASES = ("per_100g", "per_100ml")
_LANGUAGE = re.compile(r"[a-z]{2,3}")


@dataclass(frozen=True)
class Food:
    namespace: str
    local_id: str
    licence_group: str
    food_group_code: str
    food_group_name: str
    source_record: str

    @property
    def food_ref(self) -> str:
        return f"{self.namespace}:{self.local_id}"


@dataclass(frozen=True)
class FoodName:
    food_ref: str
    language: str
    name: str
    is_primary: bool


@dataclass(frozen=True)
class Value:
    food_ref: str
    nutrient_id: str
    basis: str
    amount: float | None
    qualifier: str
    confidence: str
    source_value: str
    source_nutrient_id: str
    source_unit: str
    licence_group: str


def validate(foods: Sequence[Food], names: Sequence[FoodName], values: Sequence[Value],
             dictionary: Dictionary, *, namespace: str | None = None) -> list[str]:
    """Every rule a canonical row set must satisfy. An empty list means valid.

    `namespace` confines the set to one source (the canonical stage); the
    union stage passes None and every row is checked against its own source.
    """
    problems: list[str] = []

    foods_by_ref: dict[str, Food] = {}
    for f in foods:
        where = f"food {f.food_ref}"
        if namespace is not None and f.namespace != namespace:
            problems.append(f"{where}: namespace {f.namespace!r} in canonical/{namespace}")
        if f.namespace not in dictionary.sources:
            problems.append(f"{where}: namespace {f.namespace!r} is not in sources.csv")
            continue
        if not f.local_id or f.local_id != f.local_id.strip():
            problems.append(f"{where}: local_id must be non-empty and trimmed")
        if f.licence_group != dictionary.group_of(f.namespace):
            problems.append(f"{where}: licence group {f.licence_group!r}, but sources.csv says "
                            f"{dictionary.group_of(f.namespace)!r}")
        if f.food_ref in foods_by_ref:
            problems.append(f"{where}: duplicate food_ref")
        foods_by_ref[f.food_ref] = f

    primaries: Counter[str] = Counter()
    seen_names: set[tuple[str, str]] = set()
    for n in names:
        where = f"name {n.food_ref}/{n.language}"
        if n.food_ref not in foods_by_ref:
            problems.append(f"{where}: unknown food")
        if not _LANGUAGE.fullmatch(n.language):
            problems.append(f"{where}: language must be a lower-case ISO 639 code")
        if not n.name.strip():
            problems.append(f"{where}: empty name")
        if (n.food_ref, n.language) in seen_names:
            problems.append(f"{where}: two names in one language")
        seen_names.add((n.food_ref, n.language))
        primaries[n.food_ref] += n.is_primary
    for ref in foods_by_ref:
        if primaries[ref] != 1:
            problems.append(f"food {ref}: {primaries[ref]} primary names, needs exactly 1")

    seen_values: set[tuple[str, str, str]] = set()
    for v in values:
        where = f"value {v.food_ref}/{v.nutrient_id}/{v.basis}"
        food = foods_by_ref.get(v.food_ref)
        if food is None:
            problems.append(f"{where}: unknown food")
            continue
        if v.nutrient_id not in dictionary.nutrients:
            problems.append(f"{where}: unknown nutrient")
        if v.basis not in BASES:
            problems.append(f"{where}: basis must be one of {BASES}")
        qualifier = dictionary.qualifiers.get(v.qualifier)
        if qualifier is None:
            problems.append(f"{where}: unknown qualifier {v.qualifier!r}")
        elif qualifier.amount_rule == "null" and v.amount is not None:
            problems.append(f"{where}: {v.qualifier} must have no amount, got {v.amount!r} "
                            "— a token is never coerced to a number")
        elif qualifier.amount_rule == "required" and v.amount is None:
            problems.append(f"{where}: {v.qualifier} requires an amount")
        if v.amount is not None and (not math.isfinite(v.amount) or v.amount < 0):
            problems.append(f"{where}: amount {v.amount!r} is not a finite non-negative number")
        if v.qualifier == "zero_reported" and v.amount != 0:
            problems.append(f"{where}: zero_reported with amount {v.amount!r}")
        # Independent of the qualifier logic: only a cell that says zero may become 0.
        if v.amount == 0 and parse_decimal(v.source_value, decimal_comma=True) != 0:
            problems.append(f"{where}: amount 0 from source cell {v.source_value!r} "
                            "— only an explicit zero may become 0")
        if not v.source_value.strip():
            problems.append(f"{where}: source_value is empty")
        if not v.source_nutrient_id or not v.source_unit:
            problems.append(f"{where}: source_nutrient_id and source_unit are required")
        if v.licence_group != food.licence_group:
            problems.append(f"{where}: licence group {v.licence_group!r} differs from its food's "
                            f"{food.licence_group!r}")
        key = (v.food_ref, v.nutrient_id, v.basis)
        if key in seen_values:
            problems.append(f"{where}: duplicate value")
        seen_values.add(key)

    return problems

"""Turning one source cell into (amount, qualifier) — Processing Design v0.1 §2.

The most consequential bug available in this project is a one-line type
coercion that turns CoFID's `Tr` or `N` into 0. Every source goes through
`qualify`, which has no path from a non-numeric cell to a number other than
an explicit, bounded `< x`.
"""
from __future__ import annotations

import math
import re
from dataclasses import dataclass
from typing import Any, Sequence

KJ_PER_KCAL = 4.184  # thermochemical calorie
_DECIMAL = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?")


class UnrecognisedValue(ValueError):
    """A cell no rule covers. The stage fails rather than guess."""


class NegativeAmount(UnrecognisedValue):
    """A published number below zero — not a quantity. Never stored, never clamped to 0.

    Source modules may catch this one case, emit no row, and record the cell in
    their manifest's notes.rejected_values (README "Qualifying a value").
    """


@dataclass(frozen=True)
class Qualified:
    amount: float | None
    qualifier: str


def parse_decimal(text: str, *, decimal_comma: bool = False) -> float | None:
    """A plain finite decimal, or None. Never NaN, never infinity, never a token."""
    s = text.strip()
    if decimal_comma and s.count(",") == 1 and "." not in s:
        s = s.replace(",", ".")
    if not _DECIMAL.fullmatch(s):
        return None
    number = float(s)
    return number if math.isfinite(number) else None


def qualify(cell: str, *, tokens: dict[str, str], numeric_override: str = "",
            derivation_qualifier: str = "", decimal_comma: bool = False,
            bound_prefix: str = "") -> Qualified:
    """The README's seven-step rule, in order. Blank cells never get here."""
    text = cell.strip()
    if not text:
        raise UnrecognisedValue("blank cell reached qualify(); a blank cell produces no row")
    if text in tokens:
        return Qualified(None, tokens[text])
    if bound_prefix and text.startswith(bound_prefix):
        bound = parse_decimal(text[len(bound_prefix):], decimal_comma=decimal_comma)
        if bound is None or bound <= 0:
            raise UnrecognisedValue(f"{cell!r}: a bound must be a positive number")
        return Qualified(bound, "below_loq")
    number = parse_decimal(text, decimal_comma=decimal_comma)
    if number is None:
        raise UnrecognisedValue(f"{cell!r} is neither a number nor a known token")
    if number < 0:
        raise NegativeAmount(f"{cell!r}: a nutrient amount cannot be negative")
    if number == 0:
        return Qualified(0.0, "zero_reported")
    if numeric_override:
        return Qualified(number, numeric_override)
    if derivation_qualifier:
        return Qualified(number, derivation_qualifier)
    return Qualified(number, "measured")


def convert(amount: float | None, conversion: str) -> float | None:
    if amount is None or not conversion:
        return amount
    if conversion == "kj_to_kcal":
        return amount / KJ_PER_KCAL
    raise ValueError(f"unknown unit conversion {conversion!r}")


def select(candidates: Sequence[tuple[int, Qualified, Any]]) -> tuple[int, Qualified, Any] | None:
    """One value where several source columns feed one canonical nutrient.

    `candidates` are (priority, Qualified, payload). The lowest priority that
    carries a quantity wins; if none does, the lowest priority's marker is
    kept rather than dropped.
    """
    ordered = sorted(candidates, key=lambda c: c[0])
    for candidate in ordered:
        if candidate[1].qualifier != "not_analysed":
            return candidate
    return ordered[0] if ordered else None

"""The nutrient dictionary, qualifier vocabulary and licence registry — as data.

Processing Design v0.1 §6: the mapping "will be wrong in places on the first
pass. Keeping it as data means fixing it is an update, not a re-extraction."
Nothing in the pipeline hard-codes a nutrient, a qualifier or a licence group;
it all comes from ../dictionary/, cross-checked here.
"""
from __future__ import annotations

import csv
import hashlib
from dataclasses import dataclass
from pathlib import Path

DICTIONARY_DIR = Path(__file__).resolve().parent.parent / "dictionary"
FILES = ("nutrients.csv", "qualifiers.csv", "licence_groups.csv", "sources.csv",
         "nutrient_map.csv", "derivation_qualifiers.csv", "value_tokens.csv")

# unit_conversion name -> (source unit, canonical unit), compared case-insensitively.
# The empty name is the identity: the two units must already agree.
UNIT_CONVERSIONS: dict[str, tuple[str, str] | None] = {"": None, "kj_to_kcal": ("kj", "kcal")}


class DictionaryError(ValueError):
    """The dictionary contradicts itself. The message lists every problem."""


@dataclass(frozen=True)
class Nutrient:
    nutrient_id: str
    infoods_tag: str
    name: str
    unit: str
    description: str


@dataclass(frozen=True)
class Qualifier:
    qualifier: str
    has_quantity: bool
    directly_observed: bool
    amount_rule: str  # "null": amount is always empty; "required": amount is always present
    description: str


@dataclass(frozen=True)
class LicenceGroup:
    licence_group: str
    name: str
    shippable: bool
    description: str


@dataclass(frozen=True)
class Source:
    namespace: str
    dataset_id: str
    name: str
    release: str
    licence: str
    licence_group: str
    attribution: str
    url: str


@dataclass(frozen=True)
class Mapping:
    source: str
    source_nutrient_id: str
    source_nutrient_name: str
    source_unit: str
    nutrient_id: str
    priority: int
    unit_conversion: str
    numeric_qualifier_override: str
    notes: str


@dataclass(frozen=True)
class Dictionary:
    nutrients: dict[str, Nutrient]
    qualifiers: dict[str, Qualifier]
    licence_groups: dict[str, LicenceGroup]
    sources: dict[str, Source]
    mappings: tuple[Mapping, ...]
    derivations: dict[tuple[str, str], str]  # (source, code) -> qualifier
    tokens: dict[tuple[str, str], str]  # (source, exact cell text) -> qualifier
    sha256: str

    @property
    def shippable_groups(self) -> frozenset[str]:
        return frozenset(g for g, row in self.licence_groups.items() if row.shippable)

    def group_of(self, namespace: str) -> str:
        return self.sources[namespace].licence_group

    def mappings_for(self, source: str) -> dict[str, list[Mapping]]:
        """Canonical nutrient -> the source's mappings for it, highest priority first."""
        grouped: dict[str, list[Mapping]] = {}
        for mapping in self.mappings:
            if mapping.source == source:
                grouped.setdefault(mapping.nutrient_id, []).append(mapping)
        return {n: sorted(ms, key=lambda m: m.priority) for n, ms in sorted(grouped.items())}

    def tokens_for(self, source: str) -> dict[str, str]:
        return {token: q for (src, token), q in self.tokens.items() if src == source}

    def derivations_for(self, source: str) -> dict[str, str]:
        return {code: q for (src, code), q in self.derivations.items() if src == source}


def _read(directory: Path, name: str) -> list[dict[str, str]]:
    with open(directory / name, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def _flag(text: str, where: str, problems: list[str]) -> bool:
    if text not in ("true", "false"):
        problems.append(f"{where}: expected true or false, got {text!r}")
    return text == "true"


def _digest(directory: Path) -> str:
    digest = hashlib.sha256()
    for name in FILES:
        digest.update(name.encode() + b"\0" + (directory / name).read_bytes() + b"\0")
    return digest.hexdigest()


def load(directory: Path | str = DICTIONARY_DIR) -> Dictionary:
    directory = Path(directory)
    problems: list[str] = []

    nutrients: dict[str, Nutrient] = {}
    for r in _read(directory, "nutrients.csv"):
        if r["nutrient_id"] in nutrients:
            problems.append(f"nutrients.csv: duplicate nutrient_id {r['nutrient_id']}")
        if not r["unit"]:
            problems.append(f"nutrients.csv[{r['nutrient_id']}]: unit is empty")
        nutrients[r["nutrient_id"]] = Nutrient(r["nutrient_id"], r["infoods_tag"], r["name"],
                                               r["unit"], r["description"])

    qualifiers: dict[str, Qualifier] = {}
    for r in _read(directory, "qualifiers.csv"):
        where = f"qualifiers.csv[{r['qualifier']}]"
        if r["qualifier"] in qualifiers:
            problems.append(f"{where}: duplicate")
        if r["amount_rule"] not in ("null", "required"):
            problems.append(f"{where}: amount_rule must be null or required")
        qualifiers[r["qualifier"]] = Qualifier(
            r["qualifier"], _flag(r["has_quantity"], where, problems),
            _flag(r["directly_observed"], where, problems), r["amount_rule"], r["description"])

    groups: dict[str, LicenceGroup] = {}
    for r in _read(directory, "licence_groups.csv"):
        where = f"licence_groups.csv[{r['licence_group']}]"
        if r["licence_group"] in groups:
            problems.append(f"{where}: duplicate")
        groups[r["licence_group"]] = LicenceGroup(r["licence_group"], r["name"],
                                                  _flag(r["shippable"], where, problems),
                                                  r["description"])

    sources: dict[str, Source] = {}
    for r in _read(directory, "sources.csv"):
        where = f"sources.csv[{r['namespace']}]"
        if r["namespace"] in sources:
            problems.append(f"{where}: duplicate")
        if r["licence_group"] not in groups:
            problems.append(f"{where}: unknown licence group {r['licence_group']!r}")
        sources[r["namespace"]] = Source(r["namespace"], r["dataset_id"], r["name"], r["release"],
                                         r["licence"], r["licence_group"], r["attribution"], r["url"])

    mappings: list[Mapping] = []
    seen_ids: set[tuple[str, str]] = set()
    seen_priorities: set[tuple[str, str, int]] = set()
    for r in _read(directory, "nutrient_map.csv"):
        where = f"nutrient_map.csv[{r['source']} {r['source_nutrient_id']}]"
        try:
            priority = int(r["priority"])
        except ValueError:
            problems.append(f"{where}: priority {r['priority']!r} is not an integer")
            continue
        m = Mapping(r["source"], r["source_nutrient_id"], r["source_nutrient_name"], r["source_unit"],
                    r["nutrient_id"], priority, r["unit_conversion"],
                    r["numeric_qualifier_override"], r["notes"])
        if m.source not in sources:
            problems.append(f"{where}: unknown source")
        nutrient = nutrients.get(m.nutrient_id)
        if nutrient is None:
            problems.append(f"{where}: unknown nutrient {m.nutrient_id!r}")
        if (m.source, m.source_nutrient_id) in seen_ids:
            problems.append(f"{where}: mapped twice")
        seen_ids.add((m.source, m.source_nutrient_id))
        if (m.source, m.nutrient_id, m.priority) in seen_priorities:
            problems.append(f"{where}: priority {priority} repeated for {m.nutrient_id}")
        seen_priorities.add((m.source, m.nutrient_id, m.priority))
        if priority < 1:
            problems.append(f"{where}: priority must be 1 or more")
        if m.numeric_qualifier_override and m.numeric_qualifier_override not in qualifiers:
            problems.append(f"{where}: unknown override qualifier {m.numeric_qualifier_override!r}")
        if m.unit_conversion not in UNIT_CONVERSIONS:
            problems.append(f"{where}: unknown unit_conversion {m.unit_conversion!r}")
        elif nutrient is not None:
            conversion = UNIT_CONVERSIONS[m.unit_conversion]
            source_unit, canonical_unit = m.source_unit.lower(), nutrient.unit.lower()
            if conversion is None and source_unit != canonical_unit:
                problems.append(f"{where}: source unit {m.source_unit!r} is not {nutrient.unit!r} "
                                "and no unit_conversion is given")
            if conversion is not None and conversion != (source_unit, canonical_unit):
                problems.append(f"{where}: {m.unit_conversion} converts {conversion[0]} to "
                                f"{conversion[1]}, not {source_unit} to {canonical_unit}")
        mappings.append(m)

    derivations: dict[tuple[str, str], str] = {}
    for r in _read(directory, "derivation_qualifiers.csv"):
        where = f"derivation_qualifiers.csv[{r['source']} {r['code']!r}]"
        if r["source"] not in sources:
            problems.append(f"{where}: unknown source")
        if r["qualifier"] not in qualifiers:
            problems.append(f"{where}: unknown qualifier {r['qualifier']!r}")
        if (r["source"], r["code"]) in derivations:
            problems.append(f"{where}: duplicate")
        derivations[(r["source"], r["code"])] = r["qualifier"]

    tokens: dict[tuple[str, str], str] = {}
    for r in _read(directory, "value_tokens.csv"):
        where = f"value_tokens.csv[{r['source']} {r['token']!r}]"
        if r["source"] not in sources:
            problems.append(f"{where}: unknown source")
        qualifier = qualifiers.get(r["qualifier"])
        if qualifier is None:
            problems.append(f"{where}: unknown qualifier {r['qualifier']!r}")
        elif qualifier.amount_rule != "null":
            # A token carries no number. Mapping one to a qualifier that needs an
            # amount would force the pipeline to invent one — which is the bug.
            problems.append(f"{where}: a token may only map to a qualifier with no amount, "
                            f"not {r['qualifier']!r}")
        if r["token"] != r["token"].strip() or not r["token"]:
            problems.append(f"{where}: token must be non-empty and trimmed")
        if (r["source"], r["token"]) in tokens:
            problems.append(f"{where}: duplicate")
        tokens[(r["source"], r["token"])] = r["qualifier"]

    if problems:
        raise DictionaryError(f"{len(problems)} problem(s) in {directory}:\n  " + "\n  ".join(problems))
    return Dictionary(nutrients, qualifiers, groups, sources, tuple(mappings), derivations, tokens,
                      _digest(directory))

"""Quality assurance over what the pipeline wrote — the data:validate-data pass.

Independent of the source modules on purpose: every mapped raw cell is re-read
here with its own reader and compared with what canonicalise wrote, so a
parser bug cannot pass its own test. `python3 -m almanac_nutrition qa` writes
processed/qa/report.md and report.json, and exits non-zero if a hard check fails.

Hard checks — the bundle must not ship if any fails:
  fidelity   every mapped raw cell has exactly one canonical row with the same
             number, bound or token, and no canonical row lacks a raw cell
  tokens     no row whose cell is a token carries an amount; no 0 without a raw 0
  licence    every union and bundle row is shippable and agrees with sources.csv
Soft checks — reported for a person to review:
  plausibility  protein + fat + total carbohydrate + alcohol above 105 g per 100 g
  energy        Almanac's general Atwater figure against each publisher's own
"""
from __future__ import annotations

import csv
import math
import sqlite3
import statistics
from collections import Counter, defaultdict
from contextlib import closing

import openpyxl
from lxml import etree

from .canonical_io import read_canonical
from .dictionary import Dictionary, Mapping
from .lake import Lake, staged_directory, utc_now, write_json

KJ_PER_KCAL = 4.184
# What each publisher's own documentation says its tokens mean. Deliberately not read
# from dictionary/value_tokens.csv, so that a wrong mapping there is caught here.
TOKENS = {("cofid", "Tr"): "trace", ("cofid", "N"): "not_analysed",
          ("ciqual", "traces"): "trace", ("ciqual", "-"): "not_analysed"}
NO_AMOUNT = {"trace", "not_analysed"}
EXAMPLES = 12
Cells = dict[tuple[str, str, str], list[tuple[int, str, Mapping]]]


def _text(value: object) -> str:
    if value is None:
        return ""
    return repr(value) if isinstance(value, float) else str(value)


def _mapped(dictionary: Dictionary, source: str) -> dict[str, Mapping]:
    return {m.source_nutrient_id: m for m in dictionary.mappings if m.source == source}


def _number(text: str) -> float | None:
    try:
        number = float(text.replace(",", ".") if text.count(",") == 1 and "." not in text else text)
    except ValueError:
        return None
    return number if math.isfinite(number) else None


# --- Independent readers of the raw files ------------------------------------------------

def raw_usda(lake: Lake, dictionary: Dictionary) -> tuple[set[str], Cells]:
    base = lake.source_dir("usda") / "FoodData_Central_csv_2026-04-30"
    with open(base / "foundation_food.csv", newline="", encoding="utf-8-sig") as f:
        listed = {r["fdc_id"] for r in csv.DictReader(f)}
    with open(base / "food.csv", newline="", encoding="utf-8-sig") as f:
        foods = {r["fdc_id"] for r in csv.DictReader(f)
                 if r["data_type"] == "foundation_food" and r["fdc_id"] in listed}
    mapped = _mapped(dictionary, "usda")
    cells: Cells = defaultdict(list)
    with open(base / "food_nutrient.csv", newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        header = next(reader)
        fdc, nutrient, amount = header.index("fdc_id"), header.index("nutrient_id"), header.index("amount")
        for row in reader:
            m = mapped.get(row[nutrient])
            if m and row[fdc] in foods and row[amount].strip():
                cells[(f"usda:{row[fdc]}", m.nutrient_id, "per_100g")].append(
                    (m.priority, row[amount].strip(), m))
    return {f"usda:{f}" for f in foods}, cells


def raw_ciqual(lake: Lake, dictionary: Dictionary) -> tuple[set[str], Cells]:
    base = lake.source_dir("ciqual")
    root = etree.parse(str(base / "alim_2025_11_03.xml")).getroot()
    foods = {f"ciqual:{(e.findtext('alim_code') or '').strip()}" for e in root}
    mapped = _mapped(dictionary, "ciqual")
    cells: Cells = defaultdict(list)
    for _, e in etree.iterparse(str(base / "compo_2025_11_03.xml"), tag="COMPO"):
        m = mapped.get((e.findtext("const_code") or "").strip())
        text = (e.findtext("teneur") or "").strip()
        if m and text:
            cells[(f"ciqual:{(e.findtext('alim_code') or '').strip()}", m.nutrient_id, "per_100g")].append(
                (m.priority, text, m))
        e.clear()
    return foods, cells


def _sheet(path, title: str) -> list[list[object]]:
    book = openpyxl.load_workbook(path, read_only=True, data_only=True)
    try:
        return [list(row) for row in book[title].iter_rows(values_only=True)]
    finally:
        book.close()


def _at(row: list[object], index: int) -> str:
    return _text(row[index] if index < len(row) else None).strip()


def raw_cofid(lake: Lake, dictionary: Dictionary) -> tuple[set[str], Cells]:
    rows = _sheet(lake.source_dir("cofid") / "McCance_Widdowsons_Composition_of_Foods_Integrated_Dataset_2021.xlsx",
                  "1.3 Proximates")
    headings, codes = rows[0], rows[1]
    column = {_text(c).strip(): i for i, c in enumerate(codes) if c}
    code_at, group_at = headings.index("Food Code"), headings.index("Group")
    body = [(n, row) for n, row in enumerate(rows[3:], start=4) if _at(row, code_at)]
    repeats = Counter(_at(row, code_at) for _, row in body)
    mapped = _mapped(dictionary, "cofid")
    foods: set[str] = set()
    cells: Cells = defaultdict(list)
    for n, row in body:
        code = _at(row, code_at)
        ref = f"cofid:{code}" if repeats[code] == 1 else f"cofid:{code}@row{n}"
        foods.add(ref)
        # CoFID user guide p.7: alcoholic beverages (group Q) are per 100 ml.
        basis = "per_100ml" if _at(row, group_at).startswith("Q") else "per_100g"
        for source_id, m in mapped.items():
            if text := _at(row, column[source_id]):
                cells[(ref, m.nutrient_id, basis)].append((m.priority, text, m))
    return foods, cells


def raw_afcd(lake: Lake, dictionary: Dictionary) -> tuple[set[str], Cells]:
    path = lake.source_dir("ausnut") / "AFCD Release 3 - Nutrient profiles.xlsx"
    mapped = _mapped(dictionary, "afcd")
    foods: set[str] = set()
    cells: Cells = defaultdict(list)
    for title, basis in (("All solids & liquids per 100 g", "per_100g"), ("Liquids only per 100 mL", "per_100ml")):
        rows = _sheet(path, title)
        column = {" ".join(_text(h).split()): i for i, h in enumerate(rows[2])}
        for row in rows[3:]:
            if not (key := _at(row, column["Public Food Key"])):
                continue
            if basis == "per_100g":
                foods.add(f"afcd:{key}")
            for source_id, m in mapped.items():
                if text := _at(row, column[source_id]):
                    cells[(f"afcd:{key}", m.nutrient_id, basis)].append((m.priority, text, m))
    return foods, cells


READERS = {"usda": raw_usda, "ciqual": raw_ciqual, "cofid": raw_cofid, "afcd": raw_afcd}


# --- Hard checks --------------------------------------------------------------------------

def expectation(source: str, text: str) -> tuple[str, float | None]:
    """What the publisher's own documentation says a cell is: a kind and, if any, a number."""
    if (source, text) in TOKENS:
        return TOKENS[(source, text)], None
    if source == "ciqual" and text.startswith("<"):
        return "below_loq", _number(text[1:].strip())
    number = _number(text)
    if number is None:
        return "unreadable", None
    if number < 0:
        return "negative", number
    return ("zero" if number == 0 else "number"), number


def fidelity(source: str, raw_foods: set[str], cells: Cells, foods, values, manifest) -> dict:
    problems: list[str] = []
    canonical_foods = {f.food_ref for f in foods}
    for ref in sorted(raw_foods - canonical_foods):
        problems.append(f"food {ref} is in the raw file but not canonical")
    for ref in sorted(canonical_foods - raw_foods):
        problems.append(f"food {ref} is canonical but not in the raw file")
    by_key = {(v.food_ref, v.nutrient_id, v.basis): v for v in values}
    rejected = {(r["food_ref"], r["source_nutrient_id"], r.get("basis", "per_100g"))
                for r in manifest["notes"].get("rejected_values", [])}
    kinds: Counter[str] = Counter()
    for key, found in sorted(cells.items()):
        found.sort(key=lambda c: c[0])
        # The pipeline's priority rule restated: the lowest priority that is not "no number".
        _, text, m = next((c for c in found if TOKENS.get((source, c[1])) != "not_analysed"), found[0])
        kind, number = expectation(source, text)
        kinds[kind] += 1
        where, v = "/".join(key), by_key.get(key)
        if kind == "negative":
            if v is not None:
                problems.append(f"{where}: negative raw cell {text!r} became a row")
            elif (key[0], m.source_nutrient_id, key[2]) not in rejected:
                problems.append(f"{where}: negative raw cell {text!r} is not recorded as rejected")
            continue
        if v is None:
            problems.append(f"{where}: raw cell {text!r} has no canonical row")
            continue
        if (v.source_value, v.source_nutrient_id) != (text, m.source_nutrient_id):
            problems.append(f"{where}: canonical cell {v.source_value!r} ({v.source_nutrient_id}), "
                            f"raw {text!r} ({m.source_nutrient_id})")
        if kind in NO_AMOUNT:
            if v.amount is not None or v.qualifier != kind:
                problems.append(f"{where}: raw token {text!r} became {v.qualifier} {v.amount!r}")
            continue
        if kind == "unreadable":
            problems.append(f"{where}: raw cell {text!r} is unreadable but became {v.qualifier}")
            continue
        wanted = number / KJ_PER_KCAL if m.unit_conversion == "kj_to_kcal" else number
        if v.amount is None or not math.isclose(v.amount, wanted, rel_tol=1e-9, abs_tol=1e-12):
            problems.append(f"{where}: amount {v.amount!r}, raw {text!r} gives {wanted!r}")
        if kind == "zero" and v.qualifier != "zero_reported":
            problems.append(f"{where}: raw zero became {v.qualifier}")
        if kind == "below_loq" and v.qualifier != "below_loq":
            problems.append(f"{where}: raw bound {text!r} became {v.qualifier}")
        if kind == "number" and v.qualifier in NO_AMOUNT | {"zero_reported", "below_loq"}:
            problems.append(f"{where}: raw number {text!r} became {v.qualifier}")
    for key in sorted(set(by_key) - set(cells)):
        problems.append(f"{'/'.join(key)}: canonical row with no raw cell")
    return {"raw_cells": sum(kinds.values()), "raw_cells_by_kind": dict(sorted(kinds.items())),
            "canonical_values": len(values), "problems": len(problems), "examples": problems[:EXAMPLES]}


def token_invariants(values) -> dict:
    tokens = {token for _, token in TOKENS}
    carried = [v for v in values if v.source_value.strip() in tokens and v.amount is not None]
    zero = [v for v in values if v.amount == 0 and _number(v.source_value.strip()) != 0]
    by_token = Counter(v.source_value.strip() for v in values if v.source_value.strip() in tokens)
    examples = [f"{v.food_ref}/{v.nutrient_id}: {v.source_value!r} -> {v.amount!r}" for v in carried + zero]
    return {"token_rows": dict(sorted(by_token.items())), "tokens_with_amounts": len(carried),
            "zeros_without_a_raw_zero": len(zero), "problems": len(carried) + len(zero),
            "examples": examples[:EXAMPLES]}


def licence(dictionary: Dictionary, foods, values, bundle_path) -> dict:
    problems: list[str] = []
    shippable = dictionary.shippable_groups
    group_of_food = {}
    for f in foods:
        group_of_food[f.food_ref] = f.licence_group
        if f.licence_group != dictionary.group_of(f.namespace) or f.licence_group not in shippable:
            problems.append(f"food {f.food_ref}: group {f.licence_group}")
    problems += [f"value {v.food_ref}/{v.nutrient_id}: group {v.licence_group}"
                 for v in values if v.licence_group != group_of_food.get(v.food_ref)]
    in_bundle: dict[str, list[str]] = {}
    with closing(sqlite3.connect(f"file:{bundle_path}?mode=ro", uri=True)) as con:
        for table in ("nutrition_source", "nutrition_food", "nutrition_value"):
            in_bundle[table] = sorted(g for (g,) in con.execute(f"SELECT DISTINCT licence_group FROM {table}"))
            problems += [f"bundle {table}: group {g}" for g in in_bundle[table] if g not in shippable]
        problems += [f"bundle nutrition_source {ns}: no attribution"
                     for ns, text in con.execute("SELECT namespace, attribution FROM nutrition_source")
                     if not text.strip()]
    return {"groups_in_bundle": in_bundle, "problems": len(problems), "examples": problems[:EXAMPLES]}


# --- Soft checks --------------------------------------------------------------------------

def _grams(v) -> float | None:
    """A value as it enters the general-Atwater sum (AlmanacCore's rule, restated here)."""
    if v is None or v.qualifier == "not_analysed":
        return None
    return 0.0 if v.qualifier in ("trace", "below_loq") else v.amount


def general_atwater(values: dict) -> tuple[float, float] | None:
    """(kcal, grams of protein + fat + total carbohydrate + alcohol), or None."""
    protein, fat = _grams(values.get("protein")), _grams(values.get("fat_total"))
    carbohydrate = _grams(values.get("carbohydrate_by_difference"))
    if carbohydrate is None:
        fibre = _grams(values.get("fibre_total_dietary"))
        available = _grams(values.get("carbohydrate_available"))
        if available is None:
            available = _grams(values.get("carbohydrate_available_monosaccharide"))
        carbohydrate = None if fibre is None or available is None else available + fibre
    if protein is None or fat is None or carbohydrate is None:
        return None
    alcohol = _grams(values.get("alcohol")) or 0.0
    return (4 * protein + 4 * carbohydrate + 9 * fat + 7 * alcohol,
            protein + fat + carbohydrate + alcohol)


def energy_and_plausibility(names, values) -> tuple[dict, dict]:
    primary = {n.food_ref: n.name for n in names if n.is_primary}
    by_pair: dict[tuple[str, str], dict] = defaultdict(dict)
    for v in values:
        by_pair[(v.food_ref, v.basis)][v.nutrient_id] = v
    sources: dict[str, dict] = defaultdict(lambda: {"pairs": 0, "general_atwater": 0, "publisher_only": 0,
                                                    "neither": 0, "ratios": [], "outliers": []})
    usda_published: list[float] = []
    implausible: list[dict] = []
    for (ref, basis), found in sorted(by_pair.items()):
        s = sources[ref.split(":", 1)[0]]
        s["pairs"] += 1
        estimate = general_atwater(found)
        published = found.get("energy_kcal")
        published_kcal = (published.amount if published is not None and published.qualifier != "below_loq"
                          else None)
        if estimate is None:
            s["publisher_only" if published_kcal is not None else "neither"] += 1
            continue
        kcal, grams = estimate
        s["general_atwater"] += 1
        if basis == "per_100g" and grams > 105:
            implausible.append({"food_ref": ref, "name": primary.get(ref, ""), "grams": round(grams, 2)})
        if published_kcal:
            s["ratios"].append(kcal / published_kcal)
            if abs(kcal - published_kcal) > max(30.0, 0.3 * published_kcal):
                s["outliers"].append({"food_ref": ref, "basis": basis, "name": primary.get(ref, ""),
                                      "general_atwater": round(kcal, 1), "published": round(published_kcal, 1)})
        if (usda := found.get("energy_general_atwater_kcal")) is not None and usda.amount is not None:
            usda_published.append(abs(kcal - usda.amount))
    energy = {}
    for ns, s in sorted(sources.items()):
        ratios = sorted(s.pop("ratios"))
        cuts = statistics.quantiles(ratios, n=20) if len(ratios) >= 20 else []
        s["ratio_general_atwater_to_published"] = (
            {"n": len(ratios), "p5": round(cuts[0], 3), "median": round(statistics.median(ratios), 3),
             "p95": round(cuts[-1], 3)} if cuts else {"n": len(ratios)})
        s["outlier_count"] = len(s["outliers"])
        s["outliers"] = sorted(s["outliers"], key=lambda o: -abs(o["general_atwater"] - o["published"]))[:EXAMPLES]
        energy[ns] = s
    if usda_published:
        energy["usda_general_atwater_agreement"] = {
            "n": len(usda_published), "median_abs_kcal": round(statistics.median(usda_published), 3),
            "over_1_kcal": sum(1 for d in usda_published if d > 1)}
    return energy, {"over_105_g": len(implausible),
                    "examples": sorted(implausible, key=lambda i: -i["grams"])[:EXAMPLES]}


# --- Report -------------------------------------------------------------------------------

def run(lake: Lake, dictionary: Dictionary) -> dict:
    union_foods, union_names, union_values, _ = read_canonical(lake.union)
    report: dict = {"generated_at": utc_now(), "dictionary_sha256": dictionary.sha256, "sources": {}}
    for ns in sorted(p.name for p in lake.canonical_root.iterdir() if p.is_dir() and not p.name.startswith(".")):
        foods, _, values, manifest = read_canonical(lake.canonical(ns))
        entry = {"foods": len(foods), "values": len(values),
                 "qualifiers": dict(sorted(Counter(v.qualifier for v in values).items()))}
        if ns in READERS:
            entry["fidelity"] = fidelity(ns, *READERS[ns](lake, dictionary), foods, values, manifest)
        else:
            entry["fidelity"] = {"problems": 0, "note": "no raw file: nothing to re-read"}
        report["sources"][ns] = entry
    report["tokens"] = token_invariants(union_values)
    report["licence"] = licence(dictionary, union_foods, union_values, lake.bundle)
    report["energy"], report["plausibility"] = energy_and_plausibility(union_names, union_values)
    report["passed"] = (all(e["fidelity"]["problems"] == 0 for e in report["sources"].values())
                        and report["tokens"]["problems"] == 0 and report["licence"]["problems"] == 0)
    with staged_directory(lake.root / "processed" / "qa") as scratch:
        write_json(scratch / "report.json", report)
        (scratch / "report.md").write_text(render(report), encoding="utf-8")
    return report


def render(report: dict) -> str:
    verdict = "PASSED" if report["passed"] else "FAILED"
    lines = [f"# Nutrition QA — {verdict}", "", f"Generated {report['generated_at']}; dictionary "
             f"`{report['dictionary_sha256'][:12]}`. Hard checks gate the bundle; soft checks are for review.",
             "", "## Hard checks", "",
             "| Source | Foods | Values | Raw cells re-read | Fidelity problems |", "|---|---:|---:|---:|---:|"]
    for ns, e in report["sources"].items():
        lines.append(f"| {ns} | {e['foods']:,} | {e['values']:,} | {e['fidelity'].get('raw_cells', 0):,} | "
                     f"{e['fidelity']['problems']} |")
    t, lic = report["tokens"], report["licence"]
    lines += ["", f"- Token rows: {t['token_rows']}. With an amount: **{t['tokens_with_amounts']}**. "
              f"Zeros without a raw zero: **{t['zeros_without_a_raw_zero']}**.",
              f"- Licence problems: **{lic['problems']}**. Groups in the bundle: {lic['groups_in_bundle']}."]
    for ns, e in report["sources"].items():
        for example in e["fidelity"].get("examples", []):
            lines.append(f"  - {ns}: {example}")
    lines += ["", "## Soft checks", "", "### Energy: Almanac general Atwater vs the publisher's figure", "",
              "| Source | Food-basis pairs | General Atwater | Publisher only | Neither | Ratio p5 / median / p95 | Outliers |",
              "|---|---:|---:|---:|---:|---|---:|"]
    for ns, s in report["energy"].items():
        if ns == "usda_general_atwater_agreement":
            continue
        r = s["ratio_general_atwater_to_published"]
        ratio = f"{r['p5']} / {r['median']} / {r['p95']}" if "median" in r else "—"
        lines.append(f"| {ns} | {s['pairs']:,} | {s['general_atwater']:,} | {s['publisher_only']:,} | "
                     f"{s['neither']:,} | {ratio} | {s['outlier_count']} |")
    if agreement := report["energy"].get("usda_general_atwater_agreement"):
        lines += ["", f"USDA publishes its own general-Atwater figure (2047): Almanac's differs by a median "
                      f"{agreement['median_abs_kcal']} kcal over {agreement['n']} foods; "
                      f"{agreement['over_1_kcal']} differ by more than 1 kcal."]
    lines += ["", "Largest differences (|Δ| > 30 kcal and > 30 %):", ""]
    for ns, s in report["energy"].items():
        for o in s.get("outliers", [])[:5]:
            lines.append(f"- {o['food_ref']} {o['name']} ({o['basis']}): {o['general_atwater']} vs "
                         f"{o['published']} kcal")
    p = report["plausibility"]
    lines += ["", f"### Plausibility: {p['over_105_g']} food(s) above 105 g of macronutrients per 100 g", ""]
    lines += [f"- {i['food_ref']} {i['name']}: {i['grams']} g" for i in p["examples"]]
    return "\n".join(lines) + "\n"


def summary(report: dict) -> str:
    fidelity_problems = sum(e["fidelity"]["problems"] for e in report["sources"].values())
    return (f"qa {'PASSED' if report['passed'] else 'FAILED'}: fidelity problems {fidelity_problems}, "
            f"token problems {report['tokens']['problems']}, licence problems {report['licence']['problems']}; "
            f"implausible {report['plausibility']['over_105_g']}; report in processed/qa/report.md")

"""Spreadsheet cells as text, for the extract stage of XLSX sources.

Extraction never types a value: a cell becomes the text a reviewer would
compare against the workbook, and canonicalise parses it through values.qualify.
"""
from __future__ import annotations

import csv
import datetime as dt
import re
from pathlib import Path
from typing import Iterable

import openpyxl

from .canonical_io import CanonicalError
from .lake import sha256_file


def sheet_file(workbook: str, title: str) -> str:
    """The extracted CSV for one sheet: `<workbook stem>__<sheet title, sanitised>.csv`."""
    return f"{Path(workbook).stem}__{re.sub(r'[^A-Za-z0-9.-]+', '_', title).strip('_')}.csv"


def cell_text(value: object, where: str) -> str:
    """One cell, unparsed: text as-is, numbers as their shortest round trip, dates in ISO 8601."""
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    if isinstance(value, (dt.datetime, dt.date, dt.time)):
        return value.isoformat()
    raise CanonicalError(f"{where}: cell of type {type(value).__name__} ({value!r}) has no "
                         "verbatim text form; refusing to extract it")


def extract_workbooks(source: Path, workbooks: Iterable[str], scratch: Path) -> list[dict]:
    """Writes every sheet of every workbook to its own CSV in `scratch`, all rows kept."""
    sheets = []
    for workbook in workbooks:
        book = openpyxl.load_workbook(source / workbook, read_only=True, data_only=True)
        try:
            for sheet in book.worksheets:
                name = sheet_file(workbook, sheet.title)
                if (scratch / name).exists():
                    raise CanonicalError(f"{workbook}: sheet {sheet.title!r} and another sheet "
                                         f"both extract to {name}")
                rows = columns = 0
                with open(scratch / name, "w", newline="", encoding="utf-8") as f:
                    writer = csv.writer(f, lineterminator="\n", quoting=csv.QUOTE_ALL)
                    for rows, row in enumerate(sheet.iter_rows(values_only=True), start=1):
                        writer.writerow([cell_text(v, f"{workbook}!{sheet.title} row {rows}")
                                         for v in row])
                        columns = max(columns, len(row))
                sheets.append({"workbook": workbook, "sheet": sheet.title, "file": name,
                               "rows": rows, "columns": columns})
        finally:
            book.close()
    return sheets


def read_sheet(extracted: Path, manifest: dict, workbook: str, title: str) -> tuple[list[list[str]], dict]:
    """An extracted sheet's rows, refused if the file changed after extraction."""
    name = sheet_file(workbook, title)
    path = extracted / name
    recorded = manifest.get("outputs", {}).get(name)
    if not path.is_file() or recorded != sha256_file(path):
        raise CanonicalError(f"{path} is missing or changed after extraction; re-run extract")
    with open(path, newline="", encoding="utf-8") as f:
        rows = list(csv.reader(f))
    return rows, {"file": f"processed/extracted/{extracted.name}/{name}", "sha256": recorded}


def cell(row: list[str], column: int) -> str:
    """A cell by position; openpyxl rows stop at their last non-empty cell."""
    return row[column] if column < len(row) else ""

"""The food-data lake on disk (Processing Design v0.1 §5).

    raw/                         immutable, verified against manifests/
    processed/extracted/{ns}/    the source's own shape
    processed/canonical/{ns}/    Almanac schema, source values preserved
    processed/union/             every canonical source, licence-tagged
    build/almanac.sqlite         what ships

Every stage writes only its own directory, through `staged_directory`, so a
failed run leaves the previous output exactly as it was.
"""
from __future__ import annotations

import csv
import hashlib
import json
import os
import shutil
import subprocess
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Iterable, Iterator

DEFAULT_ROOT = Path.home() / "ALManac-food-data"


class InputVerificationError(RuntimeError):
    """An input differs from what the collection manifest recorded."""


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        while block := f.read(1 << 20):
            digest.update(block)
    return digest.hexdigest()


def utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def tool_revision() -> str:
    """The git commit this pipeline ran from, marked dirty if uncommitted."""
    here = Path(__file__).resolve().parent
    try:
        head = subprocess.run(["git", "rev-parse", "HEAD"], cwd=here, capture_output=True,
                              text=True, check=True).stdout.strip()
        dirty = subprocess.run(["git", "status", "--porcelain", "--", "."], cwd=here.parent,
                               capture_output=True, text=True, check=True).stdout.strip()
    except (OSError, subprocess.CalledProcessError):
        return "unknown"
    return head + ("+dirty" if dirty else "")


class Lake:
    def __init__(self, root: Path | str | None = None) -> None:
        chosen = root or os.environ.get("ALMANAC_FOOD_DATA") or DEFAULT_ROOT
        self.root = Path(chosen).expanduser().resolve()

    @property
    def manifests(self) -> Path:
        return self.root / "manifests"

    @property
    def canonical_root(self) -> Path:
        return self.root / "processed" / "canonical"

    def extracted(self, namespace: str) -> Path:
        return self.root / "processed" / "extracted" / namespace

    def canonical(self, namespace: str) -> Path:
        return self.canonical_root / namespace

    @property
    def union(self) -> Path:
        return self.root / "processed" / "union"

    @property
    def bundle(self) -> Path:
        return self.root / "build" / "almanac.sqlite"

    def manifest(self, name: str) -> dict:
        return json.loads((self.manifests / f"{name}.json").read_text(encoding="utf-8"))

    def source_dir(self, manifest_name: str) -> Path:
        return self.root / self.manifest(manifest_name)["local_path"]

    def verify_inputs(self, manifest_name: str, filenames: Iterable[str]) -> list[dict]:
        """Checksums every input against the collection manifest before it is read."""
        manifest = self.manifest(manifest_name)
        recorded = {entry["filename"]: entry for entry in manifest["files"]}
        base = self.root / manifest["local_path"]
        verified = []
        for name in filenames:
            entry = recorded.get(name)
            if entry is None:
                raise InputVerificationError(f"{name} is not recorded in manifests/{manifest_name}.json")
            path = base / name
            if not path.is_file():
                raise InputVerificationError(f"{path} is missing")
            actual = sha256_file(path)
            if actual != entry["sha256"]:
                raise InputVerificationError(
                    f"{path}: sha256 {actual} differs from the manifest's {entry['sha256']}")
            verified.append({"file": str(path.relative_to(self.root)), "sha256": actual})
        return verified


@contextmanager
def staged_directory(final: Path) -> Iterator[Path]:
    """Yields an empty scratch directory that replaces `final` only on success."""
    final = Path(final)
    final.parent.mkdir(parents=True, exist_ok=True)
    scratch = final.with_name(f".{final.name}.partial")
    if scratch.exists():
        shutil.rmtree(scratch)
    scratch.mkdir()
    try:
        yield scratch
    except BaseException:
        shutil.rmtree(scratch, ignore_errors=True)
        raise
    retired = final.with_name(f".{final.name}.retired")
    if retired.exists():
        shutil.rmtree(retired)
    if final.exists():
        final.rename(retired)
    scratch.rename(final)
    shutil.rmtree(retired, ignore_errors=True)


def write_csv(path: Path, header: list[str], rows: Iterable[Iterable[object]], *,
              quote_all: bool = False) -> None:
    with open(path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f, lineterminator="\n",
                            quoting=csv.QUOTE_ALL if quote_all else csv.QUOTE_MINIMAL)
        writer.writerow(header)
        writer.writerows(rows)


def read_csv(path: Path) -> list[dict[str, str]]:
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def write_json(path: Path, payload: dict) -> None:
    path.write_text(json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
                    encoding="utf-8")


def read_json(path: Path) -> dict:
    return json.loads(Path(path).read_text(encoding="utf-8"))

